{
  "implementation": "def solve(case):
    attempts = case.get('attempts', [])
    max_attempts = case.get('max_attempts', 0)
    num = len(attempts)
    if num == 0:
        return {"decision": "stop", "memory_append": None, "next_attempt": 0}
    last = attempts[-1]
    if last['success']:
        return {"decision": "stop", "memory_append": None, "next_attempt": num}
    else:
        if num < max_attempts:
            return {
                "decision": "continue",
                "memory_append": {
                    "reflection": last['reflection'],
                    "signature": last['failure_signature']
                },
                "next_attempt": num + 1
            }
        else:
            return {"decision": "stop", "memory_append": None, "next_attempt": num}"
}
